<script setup lang="ts">
const router = useRouter(); const { $api } = useNuxtApp(); const loading = ref(false); const error = ref("");
interface UsageSummary { dailyUsed: number; dailyLimit: number; active: number; concurrentLimit: number }
const { data } = await useFetch<{ usage: UsageSummary | null }>("/api/dashboard", { $fetch: $api, default: () => ({ usage: null }) });
const usage = computed(() => data.value.usage);
async function start(payload: { url: string; document?: File; authentication?: { loginUrl: string; username: string; password: string } }) { loading.value=true; error.value=""; try { const body=new FormData(); body.append("request",JSON.stringify({url:payload.url,authentication:payload.authentication})); if(payload.document) body.append("requirements",payload.document); const result=await $api<{analysisId:string}>("/api/analyses",{method:"POST",body}); await router.push(`/analyses/${result.analysisId}`); } catch(cause:any){ error.value=cause?.data?.statusMessage||cause?.data?.data?.message||cause?.message||"분석 요청에 실패했습니다."; } finally{loading.value=false;} }
</script>
<template><div><section class="hero"><div class="hero-copy"><p class="eyebrow">URL 기반 AI QA</p><h1>URL을 넣으면,<br>실행기가 검증합니다.</h1><p class="lead">테스트할 페이지와 선택 문서를 분석해 검토 가능한 시나리오를 만들고, 사용자가 확정한 안전한 테스트만 실행합니다.</p><div v-if="usage" class="usage-summary" aria-label="분석 사용 현황"><span><strong>{{ usage.dailyUsed }}/{{ usage.dailyLimit }}</strong>오늘 사용</span><span><strong>{{ usage.active }}/{{ usage.concurrentLimit }}</strong>현재 실행</span><span><strong>1개</strong>분석 페이지</span></div></div><UrlAnalysisForm :loading="loading" @submit="start" /></section><div v-if="error" class="error-box" role="alert">{{ error }}</div><section class="section home-guide" aria-labelledby="analysis-guide-title"><div class="section-head"><div><p class="eyebrow">분석 안내</p><h2 id="analysis-guide-title">분석 전에 확인해 주세요</h2><p>입력한 URL의 현재 페이지 한 곳만 분석합니다.</p></div></div><details class="card document-guide"><summary>권장 문서 구성 보기</summary><p>기능명, 대상 화면, 사전 조건, 사용자 행동, 기대 결과, 동작 유형(페이지 이동·섹션 스크롤·팝업 등), 예외 조건을 포함하면 정확도가 높아집니다.</p><small>QA 요구사항이 부족하거나 무관한 문서는 테스트 조건을 추측하지 않고 기본 페이지 분석으로 전환합니다.</small></details><div class="guide-steps"><article class="card guide-step"><span>1단계</span><strong>선택 문서 분석</strong><p>PDF가 있으면 요구사항을 테스트 가능한 조건으로 정리합니다.</p></article><article class="card guide-step"><span>2단계</span><strong>페이지·시나리오 분석</strong><p>현재 페이지를 분석하고 시나리오를 수정·추가할 수 있게 제공합니다.</p></article><article class="card guide-step"><span>3단계</span><strong>확정 시나리오 테스트</strong><p>사용자가 확정한 시나리오만 안전한 범위에서 실행합니다.</p></article></div><div class="notice"><span aria-hidden="true">!</span><span>결제·삭제·계정 변경 등 위험 동작은 자동 실행하지 않습니다.</span></div></section></div></template>
